module max_hit_calculator #(parameter N=8) (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] start_angles [0:N-1],\n    input wire [31:0] end_angles [0:N-1],\n    input wire [N-1:0] valid,\n    output reg [7:0] max_overlap,\n    output reg done\n);\n\n// Constants\nlocalparam [31:0] TWO_PI = 32'd6283185;\n\n// State definitions\nlocalparam [2:0] IDLE = 3'b000;\nlocalparam [2:0] SPLIT = 3'b001;\nlocalparam [2:0] GEN_EVENTS = 3'b010;\nlocalparam [2:0] SORT = 3'b011;\nlocalparam [2:0] SWEEP = 3'b100;\nlocalparam [2:0] DONE = 3'b101;\n\n// Internal registers\nreg [2:0] state;\nreg [7:0] idx;\nreg [7:0] idx2;\nreg [7:0] interval_cnt;\nreg [7:0] event_cnt;\nreg [31:0] starts [0:2*N-1];\nreg [31:0] ends [0:2*N-1];\nreg [32:0] events [0:4*N-1];\nreg [7:0] count;\nreg [7:0] max_count;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        max_overlap <= 8'd0;\n        interval_cnt <= 8'd0;\n        event_cnt <= 8'd0;\n        count <= 8'd0;\n        max_count <= 8'd0;\n        idx <= 8'd0;\n        idx2 <= 8'd0;\n        // Initialize arrays in reset\n        for (integer j = 0; j < 2*N; j = j + 1) begin\n            starts[j] <= 32'd0;\n            ends[j] <= 32'd0;\n        end\n        for (integer k = 0; k < 4*N; k = k + 1) begin\n            events[k] <= 33'd0;\n        end\n    end\n    else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= SPLIT;\n                    interval_cnt <= 8'd0;\n                    event_cnt <= 8'd0;\n                    max_count <= 8'd0;\n                    idx <= 8'd0;\n                end\n            end\n\n            SPLIT: begin\n                if (idx < N) begin\n                    if (valid[idx]) begin\n                        if (start_angles[idx] <= end_angles[idx]) begin\n                            starts[interval_cnt] <= start_angles[idx];\n                            ends[interval_cnt] <= end_angles[idx];\n                            interval_cnt <= interval_cnt + 8'd1;\n                        end\n                        else begin\n                            starts[interval_cnt] <= start_angles[idx];\n                            ends[interval_cnt] <= TWO_PI;\n                            interval_cnt <= interval_cnt + 8'd1;\n                            starts[interval_cnt] <= 32'd0;\n                            ends[interval_cnt] <= end_angles[idx];\n                            interval_cnt <= interval_cnt + 8'd1;\n                        end\n                    end\n                    idx <= idx + 8'd1;\n                end\n                else begin\n                    idx <= 8'd0;\n                    state <= GEN_EVENTS;\n                end\n            end\n\n            GEN_EVENTS: begin\n                if (idx < interval_cnt) begin\n                    events[event_cnt] <= {starts[idx], 1'b1};\n                    event_cnt <= event_cnt + 8'd1;\n                    events[event_cnt] <= {ends[idx], 1'b0};\n                    event_cnt <= event_cnt + 8'd1;\n                    idx <= idx + 8'd1;\n                end\n                else begin\n                    if (event_cnt == 8'd0) begin\n                        state <= DONE;\n                    end\n                    else begin\n                        state <= SORT;\n                        idx <= 8'd0;\n                        idx2 <= 8'd0;\n                    end\n                end\n            end\n\n            SORT: begin\n                if (idx < event_cnt - 8'd1) begin\n                    if (idx2 < event_cnt - idx - 8'd1) begin\n                        if (events[idx2][32:1] > events[idx2+1][32:1] || \n                            (events[idx2][32:1] == events[idx2+1][32:1] && events[idx2][0] > events[idx2+1][0])) begin\n                            events[idx2] <= events[idx2+1];\n                            events[idx2+1] <= events[idx2];\n                        end\n                        idx2 <= idx2 + 8'd1;\n                    end\n                    else begin\n                        idx <= idx + 8'd1;\n                        idx2 <= 8'd0;\n                    end\n                end\n                else begin\n                    state <= SWEEP;\n                    idx <= 8'd0;\n                    count <= 8'd0;\n                    max_count <= 8'd0;\n                end\n            end\n\n            SWEEP: begin\n                if (idx < event_cnt) begin\n                    if (events[idx][0]) begin\n                        count <= count + 8'd1;\n                        if (count + 8'd1 > max_count) begin\n                            max_count <= count + 8'd1;\n                        end\n                    end\n                    else begin\n                        count <= count - 8'd1;\n                    end\n                    idx <= idx + 8'd1;\n                end\n                else begin\n                    state <= DONE;\n                end\n            end\n\n            DONE: begin\n                max_overlap <= max_count;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule